721	/* PKCS12_handle_safe_bag parses a single SafeBag element in a PKCS#12
722	 * structure. */
723	static int PKCS12_handle_safe_bag(CBS *safe_bag, struct pkcs12_context *ctx) {
724	  CBS bag_id, wrapped_value;
725	  if (!CBS_get_asn1(safe_bag, &bag_id, CBS_ASN1_OBJECT) ||
726	      !CBS_get_asn1(safe_bag, &wrapped_value,
727	                        CBS_ASN1_CONTEXT_SPECIFIC | CBS_ASN1_CONSTRUCTED | 0)
728	      /* Ignore the bagAttributes field. */) {
729	    OPENSSL_PUT_ERROR(PKCS8, PKCS8_R_BAD_PKCS12_DATA);
730	    return 0;
731	  }
732	
733	  int nid = OBJ_cbs2nid(&bag_id);
734	  if (nid == NID_pkcs8ShroudedKeyBag) {
735	    /* See RFC 7292, section 4.2.2. */
736	    if (*ctx->out_key) {
737	      OPENSSL_PUT_ERROR(PKCS8, PKCS8_R_MULTIPLE_PRIVATE_KEYS_IN_PKCS12);
738	      return 0;
739	    }
740	
741	    if (CBS_len(&wrapped_value) > LONG_MAX) {
742	      OPENSSL_PUT_ERROR(PKCS8, PKCS8_R_BAD_PKCS12_DATA);
743	      return 0;
744	    }
745	
746	    /* |encrypted| isn't actually an X.509 signature, but it has the same
747	     * structure as one and so |X509_SIG| is reused to store it. */
748	    const uint8_t *inp = CBS_data(&wrapped_value);
749	    X509_SIG *encrypted =
750	        d2i_X509_SIG(NULL, &inp, (long)CBS_len(&wrapped_value));
751	    if (encrypted == NULL) {
752	      OPENSSL_PUT_ERROR(PKCS8, PKCS8_R_BAD_PKCS12_DATA);
753	      return 0;
754	    }
755	    if (inp != CBS_data(&wrapped_value) + CBS_len(&wrapped_value)) {
756	      OPENSSL_PUT_ERROR(PKCS8, PKCS8_R_BAD_PKCS12_DATA);
757	      X509_SIG_free(encrypted);
758	      return 0;
759	    }
760	
761	    PKCS8_PRIV_KEY_INFO *pki =
762	        pkcs8_decrypt_raw(encrypted, ctx->password, ctx->password_len);
763	    X509_SIG_free(encrypted);
764	    if (pki == NULL) {
765	      return 0;
766	    }
767	
768	    *ctx->out_key = EVP_PKCS82PKEY(pki);
769	    PKCS8_PRIV_KEY_INFO_free(pki);
770	    return ctx->out_key != NULL;
771	  }
772	
773	  if (nid == NID_certBag) {
774	    /* See RFC 7292, section 4.2.3. */
775	    CBS cert_bag, cert_type, wrapped_cert, cert;
776	    if (!CBS_get_asn1(&wrapped_value, &cert_bag, CBS_ASN1_SEQUENCE) ||
777	        !CBS_get_asn1(&cert_bag, &cert_type, CBS_ASN1_OBJECT) ||
778	        !CBS_get_asn1(&cert_bag, &wrapped_cert,
779	                      CBS_ASN1_CONTEXT_SPECIFIC | CBS_ASN1_CONSTRUCTED | 0) ||
780	        !CBS_get_asn1(&wrapped_cert, &cert, CBS_ASN1_OCTETSTRING)) {
781	      OPENSSL_PUT_ERROR(PKCS8, PKCS8_R_BAD_PKCS12_DATA);
782	      return 0;
783	    }
784	
785	    if (OBJ_cbs2nid(&cert_type) != NID_x509Certificate) {
786	      return 1;
787	    }
788	
789	    if (CBS_len(&cert) > LONG_MAX) {
790	      OPENSSL_PUT_ERROR(PKCS8, PKCS8_R_BAD_PKCS12_DATA);
791	      return 0;
792	    }
793	
794	    const uint8_t *inp = CBS_data(&cert);
795	    X509 *x509 = d2i_X509(NULL, &inp, (long)CBS_len(&cert));
796	    if (!x509) {
797	      OPENSSL_PUT_ERROR(PKCS8, PKCS8_R_BAD_PKCS12_DATA);
798	      return 0;
799	    }
800	
801	    if (inp != CBS_data(&cert) + CBS_len(&cert)) {
802	      OPENSSL_PUT_ERROR(PKCS8, PKCS8_R_BAD_PKCS12_DATA);
803	      X509_free(x509);
804	      return 0;
805	    }
806	
807	    if (0 == sk_X509_push(ctx->out_certs, x509)) {
808	      X509_free(x509);
809	      return 0;
810	    }
811	
812	    return 1;
813	  }
814	
815	  /* Unknown element type - ignore it. */
816	  return 1;
817	}
