820	 * PKCS#12 structure. */
821	static int PKCS12_handle_content_info(CBS *content_info,
822	                                      struct pkcs12_context *ctx) {
823	  CBS content_type, wrapped_contents, contents;
824	  int nid, ret = 0;
825	  uint8_t *storage = NULL;
