827	  if (!CBS_get_asn1(content_info, &content_type, CBS_ASN1_OBJECT) ||
828	      !CBS_get_asn1(content_info, &wrapped_contents,
829	                        CBS_ASN1_CONTEXT_SPECIFIC | CBS_ASN1_CONSTRUCTED | 0) ||
830	      CBS_len(content_info) != 0) {
831	    OPENSSL_PUT_ERROR(PKCS8, PKCS8_R_BAD_PKCS12_DATA);
832	    goto err;
833	  }
