836	  if (nid == NID_pkcs7_encrypted) {
837	    /* See https://tools.ietf.org/html/rfc2315#section-13.
838	     *
839	     * PKCS#7 encrypted data inside a PKCS#12 structure is generally an
840	     * encrypted certificate bag and it's generally encrypted with 40-bit
841	     * RC2-CBC. */
842	    CBS version_bytes, eci, contents_type, ai, encrypted_contents;
843	    uint8_t *out;
844	    size_t out_len;
