846	    if (!CBS_get_asn1(&wrapped_contents, &contents, CBS_ASN1_SEQUENCE) ||
847	        !CBS_get_asn1(&contents, &version_bytes, CBS_ASN1_INTEGER) ||
848	        /* EncryptedContentInfo, see
849	         * https://tools.ietf.org/html/rfc2315#section-10.1 */
