# Create multiple PKCS12 variants with different structural properties
# Variant 1: Two SafeBags - first certBag, second certBag with localKeyId attr
# Key: second iter uses oid buffer from first - if first had longer OID it tests reuse

import struct, os

def der_len(n):
    if n < 0x80: return bytes([n])
    elif n < 0x100: return bytes([0x81, n])
    else: return bytes([0x82, n>>8, n&0xff])

def tlv(tag, value):
    if isinstance(value, str): value = value.encode()
    return bytes([tag]) + der_len(len(value)) + bytes(value)

def seq(*items): return tlv(0x30, b''.join(items))
def set_(*items): return tlv(0x31, b''.join(items))

def oid_encode(dotted):
    parts = [int(x) for x in dotted.split('.')]
    body = [parts[0]*40 + parts[1]]
    for part in parts[2:]:
        if part == 0: body.append(0)
        else:
            enc = []
            while part:
                enc.append(part & 0x7f)
                part >>= 7
            enc.reverse()
            for i, b in enumerate(enc):
                body.append(b | 0x80 if i < len(enc)-1 else b)
    return tlv(0x06, bytes(body))

def explicit(tag_n, value):
    body = value if isinstance(value, bytes) else bytes(value)
    return bytes([0xa0 | tag_n]) + der_len(len(body)) + body

def octet(data): return tlv(0x04, data)
def integer(n): return tlv(0x02, bytes([n]))

def make_pkcs12(safe_bags):
    safe_contents = seq(*safe_bags)
    inner_ci = seq(oid_encode("1.2.840.113549.1.7.1"), explicit(0, octet(safe_contents)))
    auth_safe = seq(inner_ci)
    outer_ci = seq(oid_encode("1.2.840.113549.1.7.1"), explicit(0, octet(auth_safe)))
    return seq(integer(3), outer_ci)

# Minimal cert DER
dummy_cert = seq(seq(integer(2)))

def certbag_value():
    cert_content = seq(oid_encode("1.2.840.113549.1.9.22.1"), explicit(0, octet(dummy_cert)))
    return cert_content

def attr(oid_str, val):
    return seq(oid_encode(oid_str), set_(val))

# Variant 1: CertBag with localKeyId attribute
bag1 = seq(
    oid_encode("1.2.840.113549.1.12.10.1.3"),  # certBag
    explicit(0, certbag_value()),
    set_(attr("1.2.840.113549.1.9.21", octet(b'\x01\x02\x03\x04')))
)
p12v1 = make_pkcs12([bag1])

# Variant 2: CertBag WITHOUT attributes - no bagAttributes set
bag2 = seq(
    oid_encode("1.2.840.113549.1.12.10.1.3"),
    explicit(0, certbag_value())
)
p12v2 = make_pkcs12([bag2])

# Variant 3: Two bags - first is unknown OID bag (longer OID) then certBag with friendlyName attr
bag3a = seq(
    oid_encode("1.2.840.113549.1.12.10.1.5"),   # unknown/secretBag type
    explicit(0, octet(b'\x30\x00'))
)
bag3b = seq(
    oid_encode("1.2.840.113549.1.12.10.1.3"),
    explicit(0, certbag_value()),
    set_(attr("1.2.840.113549.1.9.20", tlv(0x1e, b'\x00T\x00e\x00s\x00t')))
)
p12v3 = make_pkcs12([bag3a, bag3b])

# Variant 4: CertBag with two attributes (localKeyId then friendlyName)  
bag4 = seq(
    oid_encode("1.2.840.113549.1.12.10.1.3"),
    explicit(0, certbag_value()),
    set_(
        attr("1.2.840.113549.1.9.21", octet(b'\x01\x02\x03\x04')),
        attr("1.2.840.113549.1.9.20", tlv(0x1e, b'\x00T\x00e\x00s\x00t'))
    )
)
p12v4 = make_pkcs12([bag4])

# Variant 5: PKCS8 Key bag followed by CertBag with localKeyId
# This exercises simple_parse's first loop  
pkcs8_key = seq(
    seq(oid_encode("1.2.840.113549.1.1.1"), tlv(0x05, b'')),
